  (* [comment removed for export] *)
  Ltac osbA OUTA LJ :=
    let SOK := fresh "SOK" in
    lazymatch type of OUTA with u8arr _ ?mm ?D (map (Z_to_bv 8) ?o ++ ?j) =>
    pose proof (u8arr_store_ok asegs mm D _ (zlen o) (wa (D + zlen o)) OUTA
                  ltac:(repeat (rewrite length_app || rewrite length_map); cbn [length]; lia) eq_refl) as SOK;
    zstep;
    lazymatch goal with
    | |- evtF _ _ _ (MS _ _ _ _ _ (write_to_mem _ (wa ?E) _) _) => replace E with (D + zlen o) by (rewrite ?length_app; cbn [length]; lia)
    | |- evtF _ _ _ (MS _ _ _ _ _ (write_to_mem _ (Z_to_bv 64 ?E) _) _) => replace E with (D + zlen o) by (rewrite ?length_app; cbn [length]; lia)
    end;
    rewrite ?le1_zxbS, ?le1_lit;
    lazymatch goal with |- evtF _ _ _ (MS _ _ _ _ _ (write_to_mem _ _ [Z_to_bv 8 ?v]) _) =>
      let OUT2 := fresh "OUTA" in
      pose proof (RF_huf_fdw_kit.out_sb asegs mm D o j v OUTA ltac:(lia)) as OUT2;
      let LO2 := fresh "LO" in
      assert (LO2 : zlen (o ++ [v]) = zlen o + 1) by (rewrite length_app; cbn [length]; lia);
      let LJ2 := fresh "LJ" in
      assert (LJ2 : zlen (List.tl j) = dcap - zlen (o ++ [v])) by (rewrite RF_huf_fdw_sm.zlen_tl by lia; lia);
      clear OUTA LJ; store_done; rename OUT2 into OUTA; rename LJ2 into LJ
    end end.

  (* [comment removed for export] *)
  Ltac tb_now :=
    lazymatch goal with |- evtF _ _ _ (MS _ _ _ _ _ ?mm _) =>
    lazymatch goal with MU : munch [(DST, DST + dcap)] m0 mm, DJT : disjoint_from _ TB _ |- _ =>
      let TB1 := fresh "TB1" in pose proof (bytes_at_transport asegs _ m0 mm _ _ TBB MU DJT) as TB1
    end end.


  Definition stA_fin (r : res (list Z)) (m2 : amem) (a5v : Z) : Prop :=
    munch [(DST, DST + dcap)] m0 m2 /\ wmono asegs m0 m2 /\ mem_inv asegs m2 /\
    match r with
    | Ok l => a5v = zlen l /\ exists junk, u8arr asegs m2 DST (map (Z_to_bv 8) l ++ junk) /\ zlen junk = dcap - zlen l
    | Err e => a5v = - e /\ 0 < e < 120
    | Ub | NoFuel => False
    end.
  Definition stA_K (r : res (list Z)) : Prop :=
    forall m2 a5v (y1 y5 y6 y7 y10 y11 y12 y13 y14 y16 y17 y20 y21 y22 y23 y24 y25 y26 y27 y28 y29 y30 y31 : word),
      stA_fin r m2 a5v ->
      evtF asegs RNG Q (TX m2 a5v y1 y5 y6 y7 y10 y11 y12 y13 y14 y16 y17 y20 y21 y22 y23 y24 y25 y26 y27 y28 y29 y30 y31).
  Definition stA_inv (m1 : amem) (out : list Z) : Prop :=
    (exists junk, u8arr asegs m1 DST (map (Z_to_bv 8) out ++ junk) /\ zlen junk = dcap - zlen out)
    /\ munch [(DST, DST + dcap)] m0 m1 /\ wmono asegs m0 m1 /\ mem_inv asegs m1.

