  (* [comment removed for export] *)
  Ltac sjoin_close_inv rY :=
    let G := fresh "G" in let G' := fresh "G" in
    zstep; if_cases G; zify_cond G;
    [ lazymatch goal with KJ : forall w : word, _ |- _ => let v := reg_val rY in apply (KJ v) end
    | zstep; zstep; if_cases G'; zify_lts G'; [ lazymatch goal with KJ : forall w : word, _ |- _ => let v := reg_val rY in apply (KJ v) end
                                              | exfalso; lia ] ].
  Ltac schkJ_inv UH A rY J :=
    let b := fresh "b" in let RDB := fresh "RDB" in let CK := fresh "CK" in let SR := fresh "SR" in
    lazymatch goal with |- evtF _ _ _ (MS _ _ _ _ _ ?mg _) =>
      destruct (AF_fse_rd_base.chkB mg _ _ A (unpoisoned_appW _ _ mg _ _ UH ltac:(eassumption) ltac:(eassumption) ltac:(lia) ltac:(lia))
                  ltac:(lia) ltac:(lia)) as (b & RDB & CK & SR) end;
    zstep; rewrite sxb_sval; clear RDB;
    sjoinF rY J; [| sjoin_close_inv rY].

