  Lemma stA_ld2p : forall mm (p nb bits : Z) (xra t0 t1 t2 a0 a2 a3 a7 s5 s6 s9 s10 t3 t6 : word),
    0 <= p -> p + 8 <= zlen bs -> 0 <= nb <= 8 -> 0 <= bits - nb * 8 -> bits < 2^31 ->
    munch [(DST, DST + dcap)] m0 mm -> wmono asegs m0 mm -> bytes_at asegs mm S0 (map (Z_to_bv 8) bs) ->
    (forall (y10 y11 y22 y25 y31 : word),
        evtF asegs RNG Q (TST 0x96a2c mm xra (Z_to_bv 64 (le64v bs p)) (Z_to_bv 64 (bits - nb * 8)) t2 y10 y11 a2 a3 a7
                             (Z_to_bv 64 (S0 + p)) s5 y22 (Z_to_bv 64 bits) y25 s10 (Z_to_bv 64 2147450880) t3 (Z_to_bv 64 TB) y31)) ->
    evtF asegs RNG Q (TST 0x96ce8 mm xra t0 t1 t2 a0 (Z_to_bv 64 nb) a2 a3 a7 (Z_to_bv 64 (S0 + p)) s5 s6 (Z_to_bv 64 bits) s9 s10
                         (Z_to_bv 64 2147450880) t3 (Z_to_bv 64 TB) t6).
